#!/usr/bin/env python3
"""Write src/kilonova_tables.rs from the JSON produced by train_kilonova_prior.py.

    python scripts/generate_kilonova_tables.py kilonova_training.json --components 3
"""
import argparse
import json

HEADER = """// Generated by scripts/generate_kilonova_tables.py from the output of
// scripts/train_kilonova_prior.py ({families}). Do not edit by hand.

/// log10 T (K) of the first bandpass-table entry, and the table spacing.
pub(crate) const LOGT_MIN: f64 = {logt_min};
pub(crate) const LOGT_STEP: f64 = {logt_step};
pub(crate) const N_LOGT: usize = {n};
"""


def fmt(v, digits=17):
    return repr(float(v)) if digits == 17 else f"{v:.{digits}f}"


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("training_json")
    ap.add_argument("--components", type=int, default=3)
    ap.add_argument("--out", default="src/kilonova_tables.rs")
    args = ap.parse_args()
    d = json.load(open(args.training_json))
    logt = d["logt"]
    fams = ", ".join(f"{k}: {v} models" for k, v in d["families"].items())
    out = [HEADER.format(families=fams, logt_min=fmt(logt[0]), logt_step=fmt(round(logt[1] - logt[0], 6)), n=len(logt))]

    out.append("/// AB magnitude of a blackbody with L = 1 erg/s at 10 pc, photon-weighted through each")
    out.append("/// bandpass (sncosmo names), on the log10 T grid above.")
    out.append("pub(crate) const BANDPASS_TABLES: &[(&str, [f64; N_LOGT])] = &[")
    for name in sorted(d["tables"]):
        vals = ", ".join(f"{v:.6f}" for v in d["tables"][name])
        out.append(f'    ("{name}", [{vals}]),')
    out.append("];\n")

    out.append("/// Per-band offsets from a blackbody, c0 + c1·log10(t), keyed by the grid band.")
    out.append("pub(crate) const SED_OFFSETS: &[(char, f64, f64)] = &[")
    for b, (c0, c1) in d["offsets"].items():
        out.append(f"    ('{b}', {fmt(c0)}, {fmt(c1)}),")
    out.append("];\n")

    g = d["mixtures"][str(args.components)]
    k = len(g["weights"])
    out.append(f"/// Gaussian-mixture prior on (log_l1, a1, a2, log_t1, beta), {k} components.")
    out.append(f"pub(crate) const PRIOR_WEIGHTS: [f64; {k}] = [{', '.join(fmt(w) for w in g['weights'])}];")
    out.append(f"pub(crate) const PRIOR_MEANS: [[f64; 5]; {k}] = [")
    for m in g["means"]:
        out.append(f"    [{', '.join(fmt(v) for v in m)}],")
    out.append("];")
    out.append(f"pub(crate) const PRIOR_COVS: [[[f64; 5]; 5]; {k}] = [")
    for c in g["covs"]:
        out.append("    [")
        for row in c:
            out.append(f"        [{', '.join(fmt(v) for v in row)}],")
        out.append("    ],")
    out.append("];")
    open(args.out, "w").write("\n".join(out) + "\n")
    print(f"wrote {args.out} ({k}-component prior, {len(d['tables'])} bandpasses)")


if __name__ == "__main__":
    main()
